def strategy(history, rng):
    if not history:
        return 'C'

    n = len(history)

    # Count recent opponent cooperation over multiple windows
    def opp_coop_rate(window):
        if window > n:
            window = n
        if window == 0:
            return 1.0
        return sum(1 for i in range(n - window, n) if history[i][1] == 'C') / window

    # Detect opponent patterns and exploit
    opp_last = history[-1][1]

    # Calculate overall cooperation rate
    total_opp_c = sum(1 for h in history if h[1] == 'C')
    overall_rate = total_opp_c / n if n > 0 else 1.0

    # Look for suspiciously cooperative behavior (potential exploit attempt)
    # If opponent is very cooperative early, test them
    if n <= 3:
        # Early game: build cooperation but probe
        if n == 1:
            return 'C'
        if n == 2:
            # If they defected, retaliate
            if history[-1][1] == 'D':
                return 'D'
            return 'C'
        # n == 3
        recent_c = sum(1 for h in history if h[1] == 'C')
        if recent_c >= 3:
            return 'D'  # Test overly cooperative opponent
        if history[-1][1] == 'D':
            return 'D'
        return 'C'

    # Recent windows
    r3 = opp_coop_rate(3)
    r5 = opp_coop_rate(5)
    r10 = opp_coop_rate(10)
    r20 = opp_coop_rate(20)

    # Count consecutive defections by opponent at end
    consec_def = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            consec_def += 1
        else:
            break

    # Count consecutive cooperations by opponent at end
    consec_coop = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            consec_coop += 1
        else:
            break

    # Endgame: last few rounds, try to exploit
    remaining = 100 - n

    if remaining <= 2:
        # Last 2 rounds: if opponent likely to cooperate, defect
        if r3 >= 0.67:
            return 'D'
        if r5 >= 0.6:
            return 'D'
        return 'D' if r10 >= 0.5 else 'C'

    if remaining <= 5:
        # Aggressive exploitation near end
        if r5 >= 0.5:
            return 'D'
        # If opponent is retaliatory, cooperate to avoid punishment
        if r5 <= 0.2:
            return 'C'
        return 'D'

    if remaining <= 10:
        # Semi-aggressive
        if r10 >= 0.6:
            return 'D'
        if consec_coop >= 3:
            return 'D'
        if r5 >= 0.5:
            return 'D'
        return 'C'

    # Main game strategy

    # If opponent has defected many times in a row, punish
    if consec_def >= 3:
        return 'D'

    # If opponent just defected and was mostly defecting
    if opp_last == 'D' and r5 < 0.4:
        return 'D'

    # If opponent is mostly cooperating, cooperate
    if r10 >= 0.7:
        # Periodically test with defection
        if n % 7 == 0 and remaining > 15:
            return 'D'
        return 'C'

    # If opponent is mostly defecting, defect
    if r10 <= 0.3:
        return 'D'

    # Mixed opponent - tit for tat with forgiveness
    if opp_last == 'D':
        # Forgive occasionally if opponent shows cooperation
        if consec_coop >= 2:
            return 'C'
        if r5 >= 0.5:
            return 'C'
        return 'D'

    # Opponent cooperated
    # Check for patterns suggesting they will defect
    if consec_coop >= 5:
        # Long cooperation streak - maybe time to test
        if remaining > 20 and n > 20:
            if n % 11 == 0:
                return 'D'
        return 'C'

    # Look at opponent's response to our defections
    our_def_then_opp = []
    for i in range(1, n):
        if history[i-1][0] == 'D':
            our_def_then_opp.append(history[i][1])

    if len(our_def_then_opp) >= 2:
        opp_after_our_def = sum(1 for x in our_def_then_opp if x == 'C') / len(our_def_then_opp)
        # If opponent forgives our defections easily, exploit more
        if opp_after_our_def >= 0.6 and remaining > 20:
            if r5 >= 0.5:
                return 'D'

    # Default: cooperate if opponent recently cooperative
    if r3 >= 0.67:
        return 'C'
    if r5 >= 0.5:
        return 'C'

    return 'D'

